import json
import itertools

def solve_puzzle():
    # Houses are indexed 0..2 corresponding to "1","2","3" left to right
    houses = [0, 1, 2]

    Names = ['Eric', 'Peter', 'Arnold']
    Drinks = ['milk', 'water', 'tea']
    Vacations = ['mountain', 'city', 'beach']
    HouseStyles = ['colonial', 'victorian', 'ranch']
    Animals = ['cat', 'bird', 'horse']
    Birthdays = ['jan', 'sept', 'april']

    def left_of(i, j):  # strictly left
        return i < j

    def immediately_left_of(i, j):  # directly left
        return j - i == 1

    solutions = []

    for names_perm in itertools.permutations(Names):
        # indices for names
        idx_name = {names_perm[i]: i for i in houses}

        # Constraint 7: Peter is the person who prefers city breaks (will check with vacations)
        # Constraint 5: The person who keeps horses is Peter (check later with animals)
        # Constraint 9: Eric is the one who only drinks water (check with drinks)

        for drinks_perm in itertools.permutations(Drinks):
            idx_drink = {drinks_perm[i]: i for i in houses}

            # Constraint 9: Eric is the one who only drinks water.
            if idx_name['Eric'] != idx_drink['water']:
                continue

            for vacations_perm in itertools.permutations(Vacations):
                idx_vac = {vacations_perm[i]: i for i in houses}

                # Constraint 4: water == mountain
                if idx_drink['water'] != idx_vac['mountain']:
                    continue

                # Constraint 7: Peter == city
                if idx_name['Peter'] != idx_vac['city']:
                    continue

                for birthdays_perm in itertools.permutations(Birthdays):
                    idx_bday = {birthdays_perm[i]: i for i in houses}

                    # Constraint 8: mountain == april
                    if idx_vac['mountain'] != idx_bday['april']:
                        continue

                    # Constraint 3: jan is directly left of cat (need animals for full check)
                    # but we can keep for later after animals assigned

                    for animals_perm in itertools.permutations(Animals):
                        idx_animal = {animals_perm[i]: i for i in houses}

                        # Constraint 5: horse == Peter
                        if idx_animal['horse'] != idx_name['Peter']:
                            continue

                        # Constraint 3: jan directly left of cat
                        if not immediately_left_of(idx_bday['jan'], idx_animal['cat']):
                            continue

                        for styles_perm in itertools.permutations(HouseStyles):
                            idx_style = {styles_perm[i]: i for i in houses}

                            # Constraint 2: city directly left of victorian
                            if not immediately_left_of(idx_vac['city'], idx_style['victorian']):
                                continue

                            # Constraint 6: victorian right of beach
                            if not left_of(idx_vac['beach'], idx_style['victorian']):
                                continue

                            # Constraint 1: colonial left of milk
                            if not left_of(idx_style['colonial'], idx_drink['milk']):
                                continue

                            # All constraints satisfied, build the solution rows
                            rows = []
                            for h in houses:
                                rows.append([
                                    str(h + 1),
                                    names_perm[h],
                                    drinks_perm[h],
                                    vacations_perm[h],
                                    styles_perm[h],
                                    animals_perm[h],
                                    birthdays_perm[h]
                                ])
                            solutions.append(rows)

    # Assuming a unique solution
    if not solutions:
        raise ValueError("No solution found.")
    # If multiple solutions, pick the first (should be unique for well-posed puzzles)
    rows = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Drink", "Vacation", "HouseStyle", "Animal", "Birthday"],
            "rows": rows
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
